import csv, io, json, os, re, sys


def norm_text(s):
    s = s.casefold()
    s = "".join(ch if ch.isalnum() else " " for ch in s)
    return " ".join(s.split())


def nid(s):
    return str(s).strip().casefold()


def read_batch(path):
    """Return (batch, revision, status, records) ; record = (contest, {rank: [marks]})
    mark = ('c', id) or ('w', text)"""
    with open(path, encoding="utf-8", newline="") as f:
        text = f.read()
    lines = text.splitlines()
    recs = []
    if path.endswith(".jsonl"):
        objs = [json.loads(l) for l in lines if l.strip()]
        head, rest = objs[0], objs[1:]
        for o in rest:
            rk = {}
            for m in o.get("marks", []):
                r = int(m["rank"])
                if m.get("write_in") is not None:
                    rk.setdefault(r, []).append(("w", m["write_in"]))
                elif m.get("candidate") is not None:
                    rk.setdefault(r, []).append(("c", m["candidate"]))
            recs.append((o["contest"], rk))
        return (str(head["batch"]), int(str(head["revision"]).strip()),
                str(head["status"]).strip(), recs)
    meta = {}
    i = 0
    while i < len(lines) and (lines[i].startswith("#") or not lines[i].strip()):
        m = re.match(r"#\s*([^:]*?)\s*:\s*(.*?)\s*$", lines[i])
        if m:
            meta[m.group(1).strip().lower()] = m.group(2)
        i += 1
    rows = list(csv.reader(io.StringIO("\n".join(lines[i:]) + "\n")))
    rows = [r for r in rows if r and any(c.strip() for c in r)]
    header = [h.strip() for h in rows[0]]
    rcols = {}
    for idx, h in enumerate(header):
        m = re.fullmatch(r"rank(\d+)", h)
        if m:
            rcols[idx] = int(m.group(1))
    bi = header.index("ballot"); ci = header.index("contest")
    for r in rows[1:]:
        rk = {}
        for idx, n in rcols.items():
            if idx < len(r) and r[idx].strip():
                for part in r[idx].split("|"):
                    if part.strip() == "":
                        continue
                    if part.startswith("WI:"):
                        rk.setdefault(n, []).append(("w", part[3:]))
                    else:
                        rk.setdefault(n, []).append(("c", part))
        recs.append((r[ci].strip(), rk))
    return (meta["batch"], int(meta["revision"].strip()), meta["status"].strip(), recs)


def read_ballot(rk, contest, wi_map, cands, withdrawn):
    """Return list of rankings: ('skip',) ('pass',) ('choice', id) ('over', ids)"""
    out = []
    seen = set()
    for n in range(1, contest["max_ranks"] + 1):
        marks = set()
        for kind, v in rk.get(n, []):
            if kind == "w":
                t = norm_text(v)
                if t in wi_map:
                    marks.add(wi_map[t])
            else:
                marks.add(nid(v))
        if not marks:
            out.append(("skip",)); continue
        marks = {m for m in marks if m not in withdrawn}
        if not marks:
            out.append(("pass",)); continue
        new = {m for m in marks if m not in seen}
        seen |= marks
        if not new:
            out.append(("skip",)); continue
        if len(new) == 1:
            out.append(("choice", next(iter(new))))
        else:
            out.append(("over",))
    return out


def count_for(rankings, continuing):
    n = len(rankings)
    for i, r in enumerate(rankings):
        k = r[0]
        if k == "choice":
            if r[1] in continuing:
                return r[1]
        elif k == "over":
            return None
        elif k == "skip":
            if i + 1 < n and rankings[i + 1][0] == "skip":
                return None
            if i + 1 >= n:
                return None
    return None


def run_contest(contest, ballots):
    canon = {}
    withdrawn = set()
    for c in contest["candidates"]:
        canon[nid(c["id"])] = c["id"]
        if c.get("status") == "withdrawn":
            withdrawn.add(nid(c["id"]))
    wi_map = {}
    for w in contest.get("write_ins", []):
        canon[nid(w["id"])] = w["id"]
        for t in [w["name"]] + list(w.get("aliases", [])):
            wi_map[norm_text(t)] = nid(w["id"])
    cont = {k for k in canon if k not in withdrawn}
    lot = {nid(x): i for i, x in enumerate(contest.get("lot_order", []))}
    rl = [read_ballot(rk, contest, wi_map, canon, withdrawn) for rk in ballots]
    total = len(rl)
    rounds, hist, winner = [], [], None
    continuing = set(cont)
    while True:
        tally = {c: 0 for c in continuing}
        for r in rl:
            c = count_for(r, continuing)
            if c is not None:
                tally[c] += 1
        active = sum(tally.values())
        entry = {"round": len(rounds) + 1,
                 "tallies": {canon[c]: v for c, v in tally.items()},
                 "exhausted": total - active, "eliminated": []}
        rounds.append(entry)
        hist.append(tally)
        if active == 0:
            break
        win = [c for c, v in tally.items() if v * 2 > active]
        if win:
            winner = canon[win[0]]; break
        if len(continuing) == 1:
            winner = canon[next(iter(continuing))]; break
        zeros = [c for c, v in tally.items() if v == 0]
        if zeros:
            elim = zeros
        else:
            m = min(tally.values())
            tied = [c for c, v in tally.items() if v == m]
            for h in reversed(hist[:-1]):
                if len(tied) == 1:
                    break
                mm = min(h[c] for c in tied)
                tied = [c for c in tied if h[c] == mm]
            if len(tied) > 1:
                tied = [max(tied, key=lambda c: lot.get(c, -1))]
            elim = tied
        entry["eliminated"] = sorted(canon[c] for c in elim)
        continuing -= set(elim)
    return {"contest": contest["id"], "ballots": total, "winner": winner, "rounds": rounds}


def main():
    indir, outfile = sys.argv[1], sys.argv[2]
    with open(os.path.join(indir, "election.json"), encoding="utf-8") as f:
        el = json.load(f)
    cvr = os.path.join(indir, "cvr")
    best = {}
    for name in sorted(os.listdir(cvr)):
        p = os.path.join(cvr, name)
        if os.path.isfile(p) and (name.endswith(".csv") or name.endswith(".jsonl")):
            b, rev, st, recs = read_batch(p)
            if b not in best or rev > best[b][0]:
                best[b] = (rev, st, recs)
    by = {c["id"]: [] for c in el["contests"]}
    for rev, st, recs in best.values():
        if st != "final":
            continue
        for cid, rk in recs:
            if cid in by:
                by[cid].append(rk)
    res = {"election": el["election"],
           "contests": [run_contest(c, by[c["id"]]) for c in el["contests"]]}
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump(res, f, ensure_ascii=False)


main()
